"""Timecode in: MIDI Time Code's quarter frames and full frames, LTC read back from audio at each rate (and a
little fast), the drop-frame count, and what the show does to chase it."""
# AI: below section was generated by an AI
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np

from native import timecode as tc

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


def qf(hh, mm, ss, ff, rate_code):
    """The eight quarter-frame messages of one time."""
    vals = [ff & 15, ff >> 4, ss & 15, ss >> 4, mm & 15, mm >> 4, hh & 15, (hh >> 4) | (rate_code << 1)]
    return [[0xF1, (k << 4) | v] for k, v in enumerate(vals)]


# drop-frame: 00:01:00;02 is the first frame of minute one (;00 and ;01 skipped), 1800 frames in
check(abs(tc.to_seconds(0, 1, 0, 2, 29.97) - 1800 / 29.97) < 1e-9, "drop-frame 00:01:00;02 is frame 1800")
check(abs(tc.to_seconds(0, 10, 0, 0, 29.97) - 17982 / 29.97) < 1e-9, "drop-frame 00:10:00;00 is frame 17982")
for t in (0.0, 59.9, 60.04, 600.0, 3725.5):
    for fps in (24.0, 25.0, 29.97, 30.0):
        back = tc.to_seconds(*tc.from_seconds(t, fps), fps)
        if not -1e-6 <= t - back < 1.0 / fps:
            check(False, f"from_seconds({t}, {fps}) round trip: {back}")
check(True, "from_seconds and to_seconds round trip at every rate")
check(tc.words(3725.5, 25.0) == "01:02:05:12", "words at 25: " + tc.words(3725.5, 25.0))
check(tc.parse_words("01:00:00:00") == 3600.0 and tc.parse_words("1:30") == 90.0 and tc.parse_words("x") is None,
      "parse_words")

# MTC: a time in eight quarter frames, two frames on when the eighth arrives; running between, stopped after
m = tc.Mtc()
now = 100.0
for k, msg in enumerate(qf(1, 0, 10, 5, 3)):                 # 01:00:10:05 at 30
    check(m.feed(msg, now + k / 120.0), "quarter frame taken") if k == 0 else m.feed(msg, now + k / 120.0)
t, running, fps = m.position(now + 7 / 120.0)
check(fps == 30.0 and running and abs(t - (3610 + 7 / 30.0)) < 1e-6, f"MTC time two frames on: {t} {running} {fps}")
t2, running2, _ = m.position(now + 7 / 120.0 + 0.1)
check(running2 and abs(t2 - t - 0.1) < 1e-6, "MTC runs on between quarter frames")
t3, running3, _ = m.position(now + 1.0)
check(not running3 and abs(t3 - t) < 1e-6, "MTC stopped when the quarter frames stop")
m.feed([0xF1, 0x30], now + 2.0)                                  # out of order: waits for a fresh piece 0
check(m._pieces == [None] * 8, "an out-of-order piece waits for a fresh 0")
m.feed([0xF0, 0x7F, 0x7F, 0x01, 0x01, (1 << 5) | 2, 3, 4, 5, 0xF7], now + 3.0)   # full frame: 02:03:04:05 at 25
t, running, fps = m.position(now + 3.5)
check(fps == 25.0 and not running and abs(t - (2 * 3600 + 3 * 60 + 4 + 5 / 25.0)) < 1e-6, "full frame locates, held")

# LTC: encoded and read back at each rate, starting anywhere, at 48 kHz and 44.1 kHz, and 3 % fast
for fps in (24.0, 25.0, 29.97, 30.0):
    for rate in (48000, 44100):
        start = 3600 + 61.0
        x = tc.ltc_encode(start, fps, rate, seconds=1.0)
        lt = tc.Ltc()
        for a in range(0, len(x), 512):                          # in the blocks an input stream gives
            lt.feed(x[a:a + 512], rate, now=100.0 + min(len(x), a + 512) / rate)
        t, running, f = lt.position(100.0 + len(x) / rate)
        want = start + 1.0
        check(lt.frames >= int(fps) - 3 and f == fps and running and abs(t - want) < 1.5 / fps,
              f"LTC at {fps} / {rate}: {lt.frames} frames, {t:.3f} vs {want:.3f}, {f}")
x = tc.ltc_encode(10.0, 25.0, int(48000 / 1.03), seconds=1.0)  # played 3 % fast
lt = tc.Ltc()
lt.feed(x, 48000, now=1.0)
check(lt.frames >= 20 and lt.fps == 25.0, f"LTC a little fast still read ({lt.frames} frames)")
lt = tc.Ltc()
lt.feed(np.random.default_rng(0).standard_normal(48000).astype(np.float32) * 0.3, 48000, now=1.0)
check(lt.frames == 0 and lt.position(1.0)[0] is None, "noise reads as nothing")
x = tc.ltc_encode(5.0, 30.0, 48000, seconds=0.5)
lt = tc.Ltc()
lt.feed(-x * 0.05, 48000, now=1.0)                               # upside down and quiet
check(lt.frames >= 10, "LTC upside down and quiet read")

# chase: plays when it runs, seeks when far off, holds when it stops, stops before the show's start
check(tc.chase((None, False), 3605.0, True, offset=3600.0) == ("play", 5.0), "chase starts the show")
check(tc.chase((5.05, True), 3605.0, True, offset=3600.0) is None, "chase leaves a show close enough")
check(tc.chase((4.5, True), 3605.0, True, offset=3600.0) == ("seek", 5.0), "chase seeks a show drifted off")
check(tc.chase((5.0, True), 3605.0, False, offset=3600.0) == ("pause", 5.0), "chase holds when it stops")
check(tc.chase((5.0, False), 3605.0, False, offset=3600.0) is None, "chase leaves a held show held")
check(tc.chase((5.0, True), 3500.0, True, offset=3600.0) == ("stop", None), "chase stops before the start")
check(tc.chase((None, False), None, False) is None, "no timecode: nothing")

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
# AI: end
